package org.telegram.messenger;
import android.content.*;
import android.net.Uri;
import android.util.TypedValue;
import android.widget.*;
import org.telegram.tgnet.ConnectionsManager;
import org.telegram.ui.ActionBar.AlertDialog;
import org.telegram.ui.ActionBar.Theme;
import java.io.*;
import java.lang.reflect.Field;
import java.net.HttpURLConnection;
import java.net.URL;
import java.util.*;
import java.util.regex.*;

public class DrgProxy {
  private static final Map<String,String> countryCache=Collections.synchronizedMap(new HashMap<>());
  private static String pStr(Object p,String... nms){if(p==null)return "";for(String n:nms){try{Field f=p.getClass().getDeclaredField(n);f.setAccessible(true);Object v=f.get(p);return v!=null?v.toString():"";}catch(Throwable ignored){}}return "";}
  private static int pInt(Object p,String... nms){if(p==null)return 1080;for(String n:nms){try{Field f=p.getClass().getDeclaredField(n);f.setAccessible(true);return f.getInt(p);}catch(Throwable ignored){}}return 1080;}
  private static long pLong(Object p,String... nms){if(p==null)return 0L;for(String n:nms){try{Field f=p.getClass().getDeclaredField(n);f.setAccessible(true);return f.getLong(p);}catch(Throwable ignored){}}return 0L;}
  private static boolean pBool(Object p,String... nms){if(p==null)return false;for(String n:nms){try{Field f=p.getClass().getDeclaredField(n);f.setAccessible(true);return f.getBoolean(p);}catch(Throwable ignored){}}return false;}
  private static void pSet(Object p,Object val,String... nms){if(p==null)return;for(String n:nms){try{Field f=p.getClass().getDeclaredField(n);f.setAccessible(true);f.set(p,val);return;}catch(Throwable ignored){}}}
  private static String pAddr(Object p){return pStr(p,"address","ip","host","server");}
  private static int pPort(Object p){return pInt(p,"port");}
  private static String pUser(Object p){return pStr(p,"username","user");}
  private static String pPass(Object p){return pStr(p,"password","pass");}
  private static String pSec(Object p){return pStr(p,"secret");}
  private static String tgStr(String k,String uk,String ru,String en){return DrgPluginManager.tgStr(k,uk,ru,en);}
  private static String tr(String uk,String ru,String en){return DrgPluginManager.tr(uk,ru,en);}

  public static void applyProxyNow(SharedConfig.ProxyInfo p,boolean en){try{SharedPreferences.Editor ed=MessagesController.getGlobalMainSettings().edit();ed.putBoolean("proxy_enabled",en);if(p!=null){SharedConfig.currentProxy=p;ed.putString("proxy_ip",pAddr(p)).putInt("proxy_port",pPort(p)).putString("proxy_pass",pPass(p)).putString("proxy_user",pUser(p)).putString("proxy_secret",pSec(p));}ed.apply();if(en&&p!=null)ConnectionsManager.setProxySettings(true,pAddr(p),pPort(p),pUser(p),pPass(p),pSec(p));else ConnectionsManager.setProxySettings(false,"",1080,"","","");NotificationCenter.getGlobalInstance().postNotificationName(NotificationCenter.proxySettingsChanged);}catch(Throwable ignored){}}

  public static void pingProxy(final SharedConfig.ProxyInfo p,final Runnable onDone){if(p==null)return;pSet(p,Boolean.TRUE,"checking");final int a=UserConfig.selectedAccount;ConnectionsManager.getInstance(a).checkProxy(pAddr(p),pPort(p),pUser(p),pPass(p),pSec(p),time->DrgPluginManager.H.post(()->{pSet(p,Boolean.FALSE,"checking");if(time>0){pSet(p,Boolean.TRUE,"available");pSet(p,Long.valueOf(time),"ping");}else{pSet(p,Boolean.FALSE,"available");pSet(p,Long.valueOf(0L),"ping");}if(onDone!=null)onDone.run();}));}

  private static void fetchCountryAsync(final String addr,final TextView tv){if(addr==null||addr.isEmpty())return;String cached=countryCache.get(addr);if(cached!=null){tv.setText(cached);return;}new Thread(()->{String cName="—";try{HttpURLConnection con=(HttpURLConnection)new URL("http://ip-api.com/json/"+Uri.encode(addr)+"?fields=countryCode,country&lang="+DrgPluginManager.lang()).openConnection();con.setConnectTimeout(3500);con.setReadTimeout(3500);try(BufferedReader br=new BufferedReader(new InputStreamReader(con.getInputStream(),"UTF-8"))){String s=br.readLine();if(s!=null){Matcher mc=Pattern.compile("\"countryCode\"\\s*:\\s*\"([A-Z]{2})\"").matcher(s);if(mc.find()){String iso=mc.group(1);String loc=new Locale("",iso).getDisplayCountry(Locale.getDefault());if(loc!=null&&!loc.isEmpty())cName=loc;}if("—".equals(cName)){Matcher m=Pattern.compile("\"country\"\\s*:\\s*\"([^\"]+)\"").matcher(s);if(m.find()&&!m.group(1).isEmpty())cName=m.group(1);}}}}catch(Throwable ignored){}final String fc=cName;countryCache.put(addr,fc);DrgPluginManager.H.post(()->{try{tv.setText(fc);}catch(Throwable ignored){}});}).start();}

  public static void openProxyManagerDialog(final Context ctx){try{SharedConfig.loadProxyList();final List<String> items=new ArrayList<>();final boolean proxyEn=MessagesController.getGlobalMainSettings().getBoolean("proxy_enabled",false);items.add((proxyEn?"🟢 ":"⚪ ")+tgStr("UseProxySettings","Використовувати проксі","Использовать прокси","Use Proxy")+": "+(proxyEn?"ON":"OFF"));items.add("🔄 "+tgStr("Refresh","Оновити","Обновить","Refresh"));items.add("🗑️ "+tgStr("Delete","Видалити","Удалить","Delete")+" ("+tgStr("Unavailable","Недоступний","Недоступен","Unavailable")+")");items.add("➕ "+tgStr("AddProxy","Додати проксі","Добавить прокси","Add Proxy"));final ArrayList<SharedConfig.ProxyInfo> list=new ArrayList<>(SharedConfig.proxyList);for(SharedConfig.ProxyInfo p:list){boolean cur=SharedConfig.currentProxy==p&&proxyEn,chk=pBool(p,"checking"),av=pBool(p,"available");long pg=pLong(p,"ping");String st=chk?tgStr("Checking","Перевірка...","Проверка...","Checking..."):(av?(pg+" ms"):tgStr("Unavailable","Недоступний","Недоступен","Unavailable"));items.add((cur?"✓ ":"• ")+pAddr(p)+":"+pPort(p)+"  —  "+st);}new AlertDialog.Builder(ctx).setTitle(tgStr("ProxySettings","Налаштування проксі","Настройки прокси","Proxy Settings")).setItems(items.toArray(new String[0]),(d,w)->{if(w==0){boolean nx=!proxyEn;if(nx&&SharedConfig.currentProxy==null&&!SharedConfig.proxyList.isEmpty())SharedConfig.currentProxy=SharedConfig.proxyList.get(0);applyProxyNow(SharedConfig.currentProxy,nx);openProxyManagerDialog(ctx);}else if(w==1){if(SharedConfig.proxyList.isEmpty()){openProxyManagerDialog(ctx);return;}DrgPluginManager.toast(tgStr("Checking","Перевірка...","Проверка...","Checking..."));final int[] left={SharedConfig.proxyList.size()};for(SharedConfig.ProxyInfo p:SharedConfig.proxyList){pingProxy(p,()->{left[0]--;if(left[0]<=0)openProxyManagerDialog(ctx);});}}else if(w==2){int rem=0;for(int i=SharedConfig.proxyList.size()-1;i>=0;i--){SharedConfig.ProxyInfo p=SharedConfig.proxyList.get(i);if(!pBool(p,"available")&&pLong(p,"ping")<=0){SharedConfig.deleteProxy(p);rem++;}}DrgPluginManager.toast(tgStr("Delete","Видалити","Удалить","Delete")+": "+rem);openProxyManagerDialog(ctx);}else if(w==3){openAddProxyDialog(ctx);}else{int idx=w-4;if(idx>=0&&idx<list.size())openProxyDetailDialog(ctx,list.get(idx));}}).setNegativeButton(tgStr("Close","Закрити","Закрыть","Close"),null).show();}catch(Throwable ignored){}}

  private static void openAddProxyDialog(final Context ctx){try{final EditText et=new EditText(ctx);et.setHint("tg://proxy?server=... / ip:port:secret");et.setTextColor(Theme.getColor(Theme.key_dialogTextBlack));et.setHintTextColor(Theme.getColor(Theme.key_dialogTextGray3));int pad=AndroidUtilities.dp(18);et.setPadding(pad,pad,pad,pad);new AlertDialog.Builder(ctx).setTitle(tgStr("AddProxy","Додати проксі","Добавить прокси","Add Proxy")).setView(et).setPositiveButton(tgStr("Add","Додати","Добавить","Add"),(d,w)->{try{String s=et.getText().toString().trim(),srv="",usr="",pwd="",sec="";int prt=1080;if(s.contains("server=")){Uri u=Uri.parse(s.replace("tg://","https://t.me/"));srv=u.getQueryParameter("server");String ps=u.getQueryParameter("port");if(ps!=null)prt=Integer.parseInt(ps);usr=u.getQueryParameter("user");pwd=u.getQueryParameter("pass");sec=u.getQueryParameter("secret");}else if(s.contains(":")){String[] pt=s.split(":");srv=pt[0];prt=Integer.parseInt(pt[1]);if(pt.length>2)sec=pt[2];}if(srv!=null&&!srv.isEmpty()){SharedConfig.ProxyInfo pi=new SharedConfig.ProxyInfo(srv,prt,usr!=null?usr:"",pwd!=null?pwd:"",sec!=null?sec:"");SharedConfig.addProxy(pi);pingProxy(pi,()->openProxyManagerDialog(ctx));}}catch(Throwable ignored){}}).setNegativeButton(tgStr("Cancel","Скасувати","Отмена","Cancel"),(d,w)->openProxyManagerDialog(ctx)).show();}catch(Throwable ignored){}}

  private static void openProxyDetailDialog(final Context ctx,final SharedConfig.ProxyInfo p){try{LinearLayout box=new LinearLayout(ctx);box.setOrientation(LinearLayout.VERTICAL);int pad=AndroidUtilities.dp(20);box.setPadding(pad,AndroidUtilities.dp(12),pad,AndroidUtilities.dp(8));String sec=pSec(p),usr=pUser(p),addr=pAddr(p);boolean isMt=!sec.isEmpty(),av=pBool(p,"available"),chk=pBool(p,"checking");long pg=pLong(p,"ping");final TextView[] countryTv={null},statusTv={null};String[][] rows={{tr("Тип","Тип","Type"),isMt?"MTProto":"SOCKS5"},{tgStr("Country","Країна","Страна","Country"),"..."},{tgStr("UseProxyAddress","Сервер","Сервер","Server"),addr},{tgStr("UseProxyPort","Порт","Порт","Port"),String.valueOf(pPort(p))},{isMt?tgStr("UseProxySecret","Секрет","Секрет","Secret"):tgStr("UseProxyUsername","Логін","Логин","Username"),isMt?sec:(!usr.isEmpty()?usr:"—")},{tr("Статус","Статус","Status"),chk?tgStr("Checking","Перевірка...","Проверка...","Checking..."):(av?(pg+" ms"):tr("Перевірити","Проверить","Check"))}};
  for(int i=0;i<rows.length;i++){LinearLayout r=new LinearLayout(ctx);r.setOrientation(LinearLayout.HORIZONTAL);r.setPadding(0,AndroidUtilities.dp(8),0,AndroidUtilities.dp(8));TextView k=new TextView(ctx);k.setText(rows[i][0]);k.setTextColor(Theme.getColor(Theme.key_dialogTextGray2));k.setTextSize(TypedValue.COMPLEX_UNIT_DIP,14);r.addView(k,new LinearLayout.LayoutParams(AndroidUtilities.dp(95),-2));TextView v=new TextView(ctx);v.setText(rows[i][1]);v.setTextColor(i==5?(av?0xFF4CAF50:Theme.getColor(Theme.key_dialogTextBlue2)):Theme.getColor(Theme.key_dialogTextBlack));v.setTextSize(TypedValue.COMPLEX_UNIT_DIP,14);if(i==1)countryTv[0]=v;if(i==5){statusTv[0]=v;r.setOnClickListener(clk->{statusTv[0].setText(tgStr("Checking","Перевірка...","Проверка...","Checking..."));pingProxy(p,()->{if(pBool(p,"available")){statusTv[0].setTextColor(0xFF4CAF50);statusTv[0].setText(pLong(p,"ping")+" ms");}else{statusTv[0].setTextColor(0xFFE53935);statusTv[0].setText(tgStr("Unavailable","Недоступний","Недоступен","Unavailable"));}});});}r.addView(v,new LinearLayout.LayoutParams(0,-2,1f));box.addView(r);}
  fetchCountryAsync(addr,countryTv[0]);if(!av&&!chk)pingProxy(p,()->{if(statusTv[0]!=null){if(pBool(p,"available")){statusTv[0].setTextColor(0xFF4CAF50);statusTv[0].setText(pLong(p,"ping")+" ms");}else{statusTv[0].setTextColor(0xFFE53935);statusTv[0].setText(tgStr("Unavailable","Недоступний","Недоступен","Unavailable"));}}});
  new AlertDialog.Builder(ctx).setTitle(tgStr("Proxy","Проксі-сервер","Прокси-сервер","Proxy Server")).setView(box).setPositiveButton(tgStr("ConnectToProxy","Під'єднатися","Подключиться","Connect"),(d,w)->applyProxyNow(p,true)).setNeutralButton(tgStr("Delete","Видалити","Удалить","Delete"),(d,w)->{SharedConfig.deleteProxy(p);openProxyManagerDialog(ctx);}).setNegativeButton(tgStr("Close","Закрити","Закрыть","Close"),(d,w)->openProxyManagerDialog(ctx)).show();}catch(Throwable ignored){}}
}
